CREATE OR REPLACE FUNCTION private.progression_lifecycle() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN RETURN NEW; END$$; CREATE OR REPLACE FUNCTION private.progression_note_added() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN RETURN NEW; END$$; CREATE OR REPLACE FUNCTION private.progression_tick() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN RETURN 0; END$$;
COMMENT ON TABLE public.signal_progression_periods IS 'DEPRECATED: periodic note deadlines retired 2026-11-09; preserve history.'; COMMENT ON TABLE public.signal_progression_assignments IS 'DEPRECATED: periodic note assignments retained for audit, acceptance uses original event/note history.'; COMMENT ON TABLE public.signal_progression_config IS 'DEPRECATED: no new periodic note requirements.';
CREATE OR REPLACE VIEW public.signal_list_priority WITH (security_invoker=true) AS SELECT s.*,CASE WHEN s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') THEN 3 WHEN s.assigned_to IS NULL AND s.status IS NULL THEN 0 WHEN s.status='waiting' THEN 1 ELSE 2 END list_priority,CASE WHEN s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') THEN NULL::timestamptz WHEN s.assigned_to IS NULL AND s.status IS NULL THEN coalesce(a.unassigned_at,s.created_at) WHEN s.status='waiting' THEN coalesce(greatest(a.assigned_at,n.waiting_at,s.assigned_at),s.created_at) ELSE NULL::timestamptz END list_wait_since,greatest(s.updated_at,n.activity_at) list_activity_at,CASE WHEN s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') THEN 3 WHEN s.assigned_to IS NULL AND s.status IS NULL THEN 0 WHEN s.status='waiting' THEN 1 ELSE 2 END list_work_priority,NULL::date list_progression_due_on FROM public.opportunity_signals s LEFT JOIN LATERAL(SELECT max(e.created_at) FILTER(WHERE e.detail ? 'to' AND e.detail->'to'='null'::jsonb) unassigned_at,max(e.created_at) FILTER(WHERE e.detail->>'to'=s.assigned_to::text) assigned_at FROM opportunity_signal_events e WHERE e.signal_id=s.id AND e.kind='assign') a ON true LEFT JOIN LATERAL(SELECT max(j.created_at) FILTER(WHERE j.status_to='waiting' AND j.status_from IS DISTINCT FROM j.status_to) waiting_at,max(j.created_at) activity_at FROM opportunity_signal_notes j WHERE j.signal_id=s.id) n ON true;
REVOKE ALL ON public.signal_list_priority FROM PUBLIC,anon,authenticated,service_role; GRANT SELECT ON public.signal_list_priority TO authenticated,service_role;
CREATE FUNCTION public.signal_note_save(_id uuid,_request_id uuid,_note text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE s opportunity_signals;n opportunity_signal_notes;result uuid;payload text;BEGIN IF auth.uid() IS NULL OR _request_id IS NULL THEN RAISE EXCEPTION 'Thiếu phiên hoặc mã thao tác';END IF;SELECT * INTO s FROM opportunity_signals WHERE id=_id FOR UPDATE;IF NOT FOUND OR NOT ((s.assigned_to=auth.uid() AND private.sig_can(auth.uid(),'signal.sale')) OR (private.sig_can(auth.uid(),'signal.manage') AND private.sig_scope_ok(auth.uid(),s.need_groups))) THEN RAISE EXCEPTION 'Không có quyền ghi diễn biến' USING ERRCODE='42501';END IF;payload:=jsonb_build_array('voluntary-note',_id,btrim(coalesce(_note,'')))::text;SELECT * INTO n FROM opportunity_signal_notes WHERE request_id=_request_id;IF FOUND THEN IF n.signal_id<>_id OR n.author_id<>auth.uid() OR n.request_payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'Mã thao tác đã dùng cho nội dung khác';END IF;RETURN n.id;END IF;IF s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') OR s.assigned_to IS NULL THEN RAISE EXCEPTION 'Tín hiệu không còn cho phép cập nhật';END IF;IF btrim(coalesce(_note,''))='' OR length(_note)>3000 THEN RAISE EXCEPTION 'Nhập diễn biến hợp lệ, tối đa 3000 ký tự';END IF;SELECT * INTO n FROM opportunity_signal_notes WHERE signal_id=_id AND author_id=auth.uid() AND request_payload=payload AND created_at>=now()-interval '60 seconds' ORDER BY created_at DESC LIMIT 1;IF FOUND THEN RETURN n.id;END IF;INSERT INTO opportunity_signal_notes(signal_id,author_id,note,status_from,status_to,request_id,request_payload,is_progression) VALUES(_id,auth.uid(),btrim(_note),s.status,s.status,_request_id,payload,true) RETURNING id INTO result;RETURN result;END$$;
REVOKE ALL ON FUNCTION public.signal_note_save(uuid,uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.signal_note_save(uuid,uuid,text) TO authenticated;